      unfold CH2.cur, CH2V.LBr. change (CH2.den E0 (nth 0 G.BLS [])) with (CH2.den E0 EVNB.BL1). rewrite (DEN E0 (CC.env_agree_refl _ _)).
      unfold gB, EBU.gB. cbn [g_rep app]. rewrite app_nil_r. exact HHp.
    + split; [exact Hinv|]. split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|].
      split; [exists 0; split; [reflexivity | unfold OFF; cbn; lia]|].
      split; [intros X; discriminate X|]. split; [exact Hlits | intros X; discriminate X].
  - exact Hfp.
Qed.
End Nested.
End EVDNU.
